// === Tab: mySketch ===
let num = 20; // let number of rows and columns for better performance
let t = 0; // let the time

function setup() {
  createCanvas(800, 600); // let to a fixed size for testing
  noStroke();
  frameRate(30);
}

function draw() {
  background(0); // let background

  t += 0.05; // let time

  for (y = 0; y < num; y++) {
    for (x = 0; x < num; x++) {
      let xPos = map(x, 0, num-1, 0, width);
      let yPos = map(y, 0, num-1, 0, height);

      // let distortion
      let distortion = sin(xPos * 0.05 + t) * cos(yPos * 0.05 + t) * 20;

      // let "gravity well" effect when mouse is pressed
      if (mousePressed) {
        let dx = xPos - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
        let dy = yPos - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
        let distance = sqrt(dx*dx + dy*dy);
        distortion -= 50 / (1 + distance * 0.1); // let square law-like effect
      }

      // let based on distortion
      let colorValue = map(distortion, -20, 20, 0, 255);
      fill(colorValue, colorValue, 255); // Blue-white gradient

      // let circle
      ellipse(xPos, yPos, 20 + distortion, 20 + distortion);
    }
  }
}

